// Источник: web-тест .qa/e2e/tests/prayer-catalog/pc-01-catalog-search.spec.ts, план .qa/e2e/specs/prayer-catalog.md, кейс .qa/tests/prayer-catalog/PC-01-catalog-search.md
// Тикет #6a86f7ff · 1765b92b8be0 «פיתוח: קטלוג תפילות עם חיפוש». Опора: F-40 AC1–AC5 · S-27.
// Карточки — элементы с подписью, содержащей «נוסח התפילה אשכנזי»; название — до « — » / «, נוסח», без «פתיחת ».
// Число карточек сравнивается по видимым на экране (Android не отдаёт элементы за пределами экрана) — до и после поиска одинаково.
import { expect, $$, driver } from '@wdio/globals';
import { byText, byTextContains, byLabel, byLabelStartsWith, tapLabel, expectVisibleText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

function cards() {
  return driver.isAndroid
    ? $$('android=new UiSelector().descriptionContains("נוסח התפילה אשכנזי")')
    : $$('-ios predicate string:name CONTAINS "נוסח התפילה אשכנזי" OR label CONTAINS "נוסח התפילה אשכנזי"');
}
async function visibleCards() {
  const shown: WebdriverIO.Element[] = [];
  for (const el of await cards()) if (await el.isDisplayed().catch(() => false)) shown.push(el);
  return shown;
}
async function titles() {
  const out: string[] = [];
  for (const el of await visibleCards()) {
    const label = (await el.getAttribute(driver.isAndroid ? 'content-desc' : 'name')) || '';
    out.push(label.split(' — ')[0].split(', נוסח')[0].replace(/^פתיחת /, ''));
  }
  return out;
}
async function search(text: string) {
  const field = await byLabel('חיפוש');
  await field.clearValue();
  if (text) await field.setValue(text);
}
async function titlesAre(expected: string[]) {
  await driver.waitUntil(async () => JSON.stringify(await titles()) === JSON.stringify(expected),
    { timeoutMsg: `Карточки не стали ${JSON.stringify(expected)}` });
}
async function countIs(n: number) {
  await driver.waitUntil(async () => (await visibleCards()).length === n, { timeoutMsg: `Карточек не ${n}` });
}

describe('Каталог молитв', () => {
  afterEach(async () => { await toHome(); });

  it('PC-01 «תפילות»: список с נוסח, поиск по синонимам и נוסח, пустое состояние, открытие #6a86f7ff @prod-safe', async () => {
    // 1. Таб «תפילות»: поиск, строка о нусахе профиля, карточки с «נוסח התפילה אשכנזי».
    await goTab('תפילות');
    await (await byLabel('חיפוש')).waitForDisplayed({ timeout: 20000 });
    await expectVisibleText('התפילות מוצגות בנוסח אשכנז שנשמר בפרופיל.');
    await driver.waitUntil(async () => (await visibleCards()).length > 0, { timeoutMsg: 'Нет карточек каталога' });
    const allCount = (await visibleCards()).length;
    expect(allCount).toBeGreaterThanOrEqual(3);
    await expect(byTextContains('נוסח התפילה אשכנזי')).toBeDisplayed();

    // 2. Запросы поиска.
    await search('מעריב');
    await titlesAre(['ערבית']);
    await search('עמידה');
    await titlesAre(['שחרית', 'מנחה', 'ערבית']);
    await search('שמונה עשרה');
    await titlesAre(['שחרית', 'מנחה', 'ערבית']);
    await search('ק״ש שעל המיטה');
    await titlesAre(['קריאת שמע על המיטה']);
    await search('קידוש לבנה');
    await titlesAre(['ברכת הלבנה']);
    await search('אשכנז');
    await countIs(allCount);
    await search('zzzqq');
    await expectVisibleText('לא נמצאו תפילות שמתאימות ל״zzzqq״.');
    await countIs(0);

    // 3. «ניקוי החיפוש» — полный список.
    await tapLabel('ניקוי החיפוש');
    await countIs(allCount);

    // 4. «מעריב» → тап по карточке (раскрывает строку) → «פתיחת ערבית» → ערבית (אשכנזי).
    await search('מעריב');
    await titlesAre(['ערבית']);
    await (await visibleCards())[0].click();
    await (await byLabelStartsWith('פתיחת ערבית')).click();
    await expect(byText('ערבית (אשכנזי)')).toBeDisplayed();
  });
});
